import{_ as r,C as n,c as i,o as t,a2 as a,b as d,w as s,a as l,G as c,a3 as u}from"./chunks/framework.DkPtUiZm.js";const q=JSON.parse('{"title":"Dates, sécurité et suivi mobiles","description":"","frontmatter":{},"headers":[],"relativePath":"guides/nouveaux-composants-mobiles.md","filePath":"guides/nouveaux-composants-mobiles.md","lastUpdated":1795096530000}'),p={name:"guides/nouveaux-composants-mobiles.md"};function m(v,e,h,f,g,b){const o=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="dates-securite-et-suivi-mobiles" tabindex="-1">Dates, sécurité et suivi mobiles <a class="header-anchor" href="#dates-securite-et-suivi-mobiles" aria-label="Permalink to &quot;Dates, sécurité et suivi mobiles&quot;">​</a></h1><p>Ce lot ajoute les 17 modules précédemment <strong>À créer</strong> dans la <a href="./../contribuer/parite-web-mobile.html">matrice web/mobile</a>. Ils restent expérimentaux et sont implémentés pour la prochaine publication. Les 13 modules auparavant <strong>À adapter</strong>, désormais couverts par le <a href="./adaptations-mobiles.html">lot suivant</a>, restent identifiés séparément ; l’agenda d’EventManager ne constitue pas une livraison des grilles spécialisées d’EventCalendar.</p><h2 id="installation-et-demonstration" tabindex="-1">Installation et démonstration <a class="header-anchor" href="#installation-et-demonstration" aria-label="Permalink to &quot;Installation et démonstration&quot;">​</a></h2><p>Depuis le workspace : <code>pnpm install</code>, puis <code>pnpm native</code>. La démo dispose de <strong>109 fiches</strong> dans <strong>Composants → Tous</strong> et de quatre nouveaux écrans :</p><table tabindex="0"><thead><tr><th>Écran</th><th>Essais proposés</th></tr></thead><tbody><tr><td>Dates et périodes</td><td>Année, mois, semaine ISO, calendrier compact, plage normale/de nuit, raccourcis ; normal, lecture seule et désactivé.</td></tr><tr><td>Sécurité et suivi</td><td>Bascules, tailles et variantes ; secrets et permissions ; JSON valide/invalide et copie ; pause/reprise des compteurs et statuts de tâche.</td></tr><tr><td>Agenda</td><td>Choix de date, création, détail, modification, suppression confirmée, lecture seule et erreur serveur simulée.</td></tr><tr><td>Journal d’activité</td><td>Recherche, filtre d’action, pagination, consultation d’une entrée, erreur et actualisation.</td></tr></tbody></table><p><code>BrandIcon</code> utilise le peer <strong>react-native-svg &gt;=15.16 &lt;16</strong> ; la démo fixe 15.16.0, compatible avec son socle Expo 58. Dans un projet Expo, utiliser <code>npx expo install react-native-svg</code> et respecter les versions du socle documenté. Il n’embarque aucune collection de logos : passer <code>{title, path, hex}</code> comme sur le web. La taille est numérique ; les marques trop sombres/claires prennent la couleur du texte lorsque leur couleur serait illisible. <code>colored={false}</code> et <code>decorative</code> permettent les usages monochromes et purement décoratifs.</p><h2 id="bascules-secrets-et-permissions" tabindex="-1">Bascules, secrets et permissions <a class="header-anchor" href="#bascules-secrets-et-permissions" aria-label="Permalink to &quot;Bascules, secrets et permissions&quot;">​</a></h2><p><code>Toggle</code> expose <code>pressed</code>, <code>defaultPressed</code>, <code>onPressedChange</code>, icône, libellé, état désactivé, taille, ton, variante et animation configurable. <code>ToggleGroup</code> propose les modes simple et multiple ; <code>deselectable={false}</code> maintient un choix en mode simple. Les composants conservent un état local si aucune valeur contrôlée n’est fournie.</p><p><code>SecretFields</code> conserve l’identité de ses lignes pendant la frappe. <code>storedKeys</code> sert à initialiser les noms existants <strong>sans aucune valeur de secret</strong> ; dans un formulaire contrôlé, fournir ces entrées dans <code>value</code> avec <code>value: &#39;&#39;</code>. Une valeur laissée vide pour un nom stocké signifie « conserver » ; saisir une nouvelle valeur signifie « remplacer ». <code>templates</code> propose des noms et <code>keyPattern</code> valide leur forme, sans dépendre de <code>RegExp.lastIndex</code>. <code>validateSecretEntries</code> expose les doublons et noms invalides au formulaire appelant. Les valeurs restent masquées par PasswordInput, sauf révélation explicite. Hors de Form, placer la saisie dans KeyboardScrollView pour garder le champ visible au-dessus du clavier ; la démo applique ce conteneur.</p><p>Le composant n’appelle aucun serveur : l’application décide de la conservation, rotation ou suppression à partir de sa liste avant/après. Ne pas sérialiser les secrets dans l’URL, les toasts ou les messages d’erreur.</p><p><code>PermissionMatrix</code> montre des sections par domaine. <code>canGrant(permission)</code> verrouille les permissions non accordables. Un joker de domaine implique ses actions et les verrouille individuellement ; le joker global <code>*</code> met l’ensemble en lecture seule. Les permissions absentes de la configuration restent dans la valeur. La sélection de tout un domaine est bloquée si elle retirerait ou accorderait un droit non modifiable. Le serveur reste responsable de l’autorisation.</p><h2 id="periodes-et-dates-civiles" tabindex="-1">Périodes et dates civiles <a class="header-anchor" href="#periodes-et-dates-civiles" aria-label="Permalink to &quot;Périodes et dates civiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Composant</th><th>Valeur et comportement</th></tr></thead><tbody><tr><td>YearPicker</td><td>Nombre, bornes <code>min</code>/<code>max</code> entre 1 et 9999, liste virtualisée à lignes de hauteur connue, validation explicite.</td></tr><tr><td>MonthPicker</td><td><code>YYYY-MM</code>, bornes du même format, navigation d’année, sélection et confirmation.</td></tr><tr><td>WeekPicker</td><td><code>YYYY-Www</code> ISO : lundi–dimanche et année de semaine ISO ; le 1er janvier peut appartenir à l’année ISO précédente.</td></tr><tr><td>MiniCalendar</td><td>Calendar compact avec ses bornes, jours désactivés, thème et choix du jour.</td></tr><tr><td>TimeRangePicker</td><td><code>{start: &#39;HH:mm&#39;, end: &#39;HH:mm&#39;}</code>, roues, pas de minutes, bornes et brouillon partagé. Fin antérieure interdite sauf <code>allowOvernight</code>.</td></tr><tr><td>DateRangeFilter</td><td>DateRangePicker contrôlé, raccourcis et <code>onClear</code> ; les bornes et la lecture seule s’appliquent aussi aux raccourcis.</td></tr></tbody></table><p>Les feuilles n’émettent que lors de la confirmation ; fermer ou revenir annule le brouillon. Mois/semaine et plage peuvent être effacés quand le contrat le prévoit ; YearPicker correspond à une sélection d’année, sans effacement. <code>isoWeekFromDate</code> et <code>isoWeekRange</code> rendent les conversions explicites et rejettent les semaines inexistantes. WeekPicker exige que les <strong>deux extrémités</strong> de la semaine respectent ses limites. Aucune conversion UTC implicite n’est appliquée aux dates civiles. TimeRangePicker autorise une traversée de minuit, pas un nombre arbitraire de journées ; les règles de fuseau et heure d’été restent applicatives.</p><p>Ces contrôles peuvent être composés directement ou reliés à <code>Form</code> via un champ <code>custom</code> et sa fonction <code>render</code>, sans changer la représentation stockée.</p><h2 id="agenda-et-evenements" tabindex="-1">Agenda et événements <a class="header-anchor" href="#agenda-et-evenements" aria-label="Permalink to &quot;Agenda et événements&quot;">​</a></h2><p><code>EventManager</code> utilise <code>CalendarEventInput</code> et <code>eventDays</code> partagés avec headless. Le natif ajoute couleur, lieu et description textuelle. <code>start</code>/<code>end</code> portent une date civile ou une date avec heure (<code>2026-11-17T09:00</code>) ; les journées de l’intervalle sont inclusives selon le contrat partagé. L’application convertit ses instants serveur dans le fuseau métier avant de les transmettre.</p>',17)),(t(),d(u,null,{default:s(()=>[c(o,{id:"mermaid-153",class:"mermaid",graph:"flowchart%20LR%0A%20%20Date%5B%22Date%20choisie%22%5D%20--%3E%20Agenda%5B%22%C3%89v%C3%A9nements%20du%20jour%22%5D%0A%20%20Agenda%20--%3E%20Detail%5B%22Fiche%20de%20l%E2%80%99%C3%A9v%C3%A9nement%22%5D%0A%20%20Create%5B%22Nouvel%20%C3%A9v%C3%A9nement%22%5D%20--%3E%20Form%5B%22Formulaire%20natif%22%5D%0A%20%20Detail%20--%3E%20Form%0A%20%20Form%20--%3E%20Validate%5B%22Titre%2C%20dates%20et%20ordre%20des%20heures%22%5D%0A%20%20Validate%20--%3E%20Save%5B%22onCreate%20%2F%20onUpdate%22%5D%0A%20%20Save%20--%3E%20Error%5B%22Erreurs%20par%20champ%20ou%20erreur%20g%C3%A9n%C3%A9rale%22%5D%0A%20%20Save%20--%3E%20Source%5B%22Liste%20mise%20%C3%A0%20jour%20par%20l%E2%80%99application%22%5D%0A%20%20Detail%20--%3E%20Confirm%5B%22Confirmation%20de%20suppression%22%5D%0A%20%20Confirm%20--%3E%20Delete%5B%22onDelete%22%5D%0A%20%20Source%20--%3E%20Agenda%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>Les callbacks de mutation sont optionnels ; leur absence masque les actions. <code>canCreate</code>, <code>canEdit</code> et <code>canDelete</code> affinent les droits. Les erreurs de champs retournées par <code>onCreate</code>/<code>onUpdate</code> restent dans le formulaire ; une exception est affichée par Form. La suppression est confirmée dans la même feuille et une exception garde une action réessayable. Les doubles appels sont verrouillés.</p><p>L’application conserve la source des événements : les callbacks doivent mettre à jour <code>events</code> après succès. Les valeurs des champs métier déjà présents sont conservées en modification. <code>date</code>/<code>onDateChange</code> permettent de charger un périmètre serveur et <code>extraFields</code>/<code>extraDefaultValues</code> ajoutent des champs métier. Une seule feuille évite d’empiler un dialogue de confirmation sur le formulaire.</p><h2 id="journal-et-json" tabindex="-1">Journal et JSON <a class="header-anchor" href="#journal-et-json" aria-label="Permalink to &quot;Journal et JSON&quot;">​</a></h2><p><code>ActivityLog</code> prend <code>entries</code>, <code>query</code> de <code>useTableQuery</code>, <code>total</code>, filtres, chargement/erreur, actualisation et callback d’ouverture. Il ne filtre ni ne repagine silencieusement les données serveur : fournir uniquement la page chargée et le total filtré, puis utiliser <code>query.params</code> dans le fetcher applicatif. Les libellés/tons d’action sont personnalisables. La démo réalise ce travail sur un petit tableau local ; le rendu reste virtualisé via ResourceList.</p><p><code>JsonView</code> accepte <code>value</code> analysée ou <code>source</code> prioritaire. Une source invalide reste visible avec une alerte. L’arbre limite profondeur et nombre de nœuds (par défaut 8 et 500), détecte les cycles et ne déclenche pas les getters pour l’affichage. <code>defaultExpandDepth</code> et <code>collapsible</code> contrôlent les branches. Le mode autonome est virtualisé ; <code>scrollable={false}</code> permet l’intégration dans un ScrollView ou le catalogue sans imbriquer des listes verticales.</p><p>La copie passe par <code>onCopy(text)</code> : la démo utilise <code>expo-clipboard</code>, qui n’est pas une dépendance du package natif. Un rejet affiche une erreur et autorise un nouvel essai. Les réponses d’une copie ancienne ne marquent pas une nouvelle source comme copiée. La copie est bornée à 10 000 valeurs et 1 000 000 de caractères ; au-delà, elle est refusée avec une erreur plutôt que de produire un export tronqué. Les valeurs non JSON comme BigInt et cycles reçoivent une représentation de debug.</p><h2 id="taches-connexion-et-temps" tabindex="-1">Tâches, connexion et temps <a class="header-anchor" href="#taches-connexion-et-temps" aria-label="Permalink to &quot;Tâches, connexion et temps&quot;">​</a></h2><p><code>JobProgress</code> affiche statut, progression, étapes, essais et durée, avec callbacks asynchrones de reprise/annulation et verrou de double appui. Il ne lance aucun job et ne crée pas de connexion : les données viennent de l’application. Succès force 100 %, tandis qu’une erreur/annulation sans progression connue affiche 0 %.</p><p><code>LiveIndicator</code> distingue connecting/open/closed, permet les libellés personnalisés et le mode compact. L’animation respecte le mouvement réduit et s’arrête en arrière-plan.</p><p><code>Timer</code> calcule le temps écoulé depuis un horodatage, dans le sens montant ou descendant. <code>running={false}</code> gèle la valeur ; la reprise continue depuis cette valeur. Le passage en arrière-plan suspend <strong>les intervalles</strong>, pas le temps écoulé : le retour au premier plan recalcule immédiatement. <code>Countdown</code> impose simplement le sens descendant. <code>onFinish</code> se déclenche une fois par durée/configuration. Changer la durée ou la clé réarme le compteur. La fréquence est configurable, avec un minimum de 16 ms ; le défaut de 250 ms suffit aux durées lisibles.</p><p>Les nouveaux composants doivent encore être essayés sur appareil, en particulier les roues, la sélection de texte/secret avec clavier, le rendu SVG, la copie et le retour au premier plan. La confirmation utilisateur des composants précédents reste enregistrée séparément.</p><h2 id="fonctions-utilisables-separement" tabindex="-1">Fonctions utilisables séparément <a class="header-anchor" href="#fonctions-utilisables-separement" aria-label="Permalink to &quot;Fonctions utilisables séparément&quot;">​</a></h2><ul><li><code>isoWeekFromDate</code> et <code>isoWeekRange</code> convertissent une date civile ou une semaine ISO.</li><li><code>validTimeRange</code> contrôle deux heures et l’option de passage à minuit.</li><li><code>validateSecretEntries</code> renvoie les indices invalides avec les codes <code>duplicate</code> ou <code>pattern</code>, à convertir en erreurs du formulaire appelant.</li><li><code>eventDraftErrors</code> contrôle les <strong>valeurs du formulaire</strong> : <code>title</code>, <code>allDay</code>, <code>startDate</code>, <code>endDate</code>, <code>startTime</code>, <code>endTime</code>. Les codes sont <code>required</code>, <code>invalid</code> et <code>order</code> ; ce ne sont pas les champs <code>start</code>/<code>end</code> du résultat EventDraft.</li><li><code>jsonViewRows</code> produit les lignes visibles et l’indicateur de troncature pour une intégration d’arbre personnalisée.</li><li><code>formatDuration</code> produit l’horloge de Timer ; son option ajoute les centièmes.</li></ul>',13))])}const D=r(p,[["render",m]]);export{q as __pageData,D as default};
